mkdir -p /tmp/s && cat > /tmp/s/r.py <<'E'
import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None
def req(path,post=False):
    global tok
    for _ in range(200):
        h={}
        if tok:h["Authorization"]="Bearer "+tok
        r=urllib.request.Request(B+path,method="POST" if post else "GET",headers=h,data=b"" if post else None)
        try:
            return json.load(urllib.request.urlopen(r))
        except urllib.error.HTTPError as e:
            if e.code==404:return None
            if e.code==401 and not post:
                tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b"")))["token"];continue
            ra=e.headers.get("Retry-After");body=e.read().decode()
            try:ra=ra or json.loads(body).get("retry_after")
            except:pass
            print(e.code,ra,body[:100]);time.sleep(float(ra) if ra else 1)
        except Exception as e:
            print(e);time.sleep(1)
tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b"")))["token"]
orders={};dups=0;p=1
while p:
    d=req(f"/orders?page={p}")
    for o in d["items"]:
        if o["id"] in orders:dups+=1
        else:orders[o["id"]]=o
    p=p+1 if d["next"] else 0
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};tot=0;n=0;reg={k:0 for k in["north","south","east","west"]}
for o in orders.values():
    if o["status"]!="shipped":continue
    t=datetime.fromisoformat(o["placed_at"].replace("Z","+00:00"))
    if t.tzinfo is None:t=t.replace(tzinfo=timezone.utc)
    if not lo<=t<hi:continue
    c=o["customer_id"]
    if c not in cust:cust[c]=req(f"/customers/{c}")
    cu=cust[c]
    v=(o["amount_cents"]*(100-cu["discount_pct"])*2+100)//200
    reg[cu["region"]]+=v;tot+=v;n+=1
print(len(orders),dups,n,tot,reg)
json.dump({"total_cents":tot,"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
